     *   <li>Multi-line strings</li>
     *   <li>YAML tags and anchors (basic support)</li>
     * </ul>
     *
     * @param yamlContent the YAML string content to parse, must not be null
     * @return the parsed Java object representing the YAML content
     * @throws IllegalArgumentException if yamlContent is null or empty
     * @throws YamlParsingException if the YAML content is malformed or cannot be parsed
     */
    public Object parseUserYaml(String yamlContent) {
        // Validate input
        if (yamlContent == null) {
            throw new IllegalArgumentException("YAML content must not be null");
        }

        String trimmedContent = yamlContent.trim();
        if (trimmedContent.isEmpty()) {
            throw new IllegalArgumentException("YAML content must not be empty");
        }

        try {
            // Create a new Yaml instance (thread-safe for parsing)
            Yaml yaml = new Yaml();

            // Parse the YAML content
            Object parsedObject = yaml.load(trimmedContent);

            // Handle edge case: YAML with only comments or whitespace returns null
            if (parsedObject == null) {
                throw new YamlParsingException(
                    "YAML content resulted in null object. " +
                    "Ensure the content contains valid YAML data."
                );
            }

            return parsedObject;

        } catch (YAMLException e) {
            // Wrap SnakeYAML exceptions with more context
            throw new YamlParsingException(
                "Failed to parse YAML content: " + e.getMessage(), e
            );
        } catch (Exception e) {
            // Catch any unexpected exceptions during parsing
            throw new YamlParsingException(
                "Unexpected error while parsing YAML content: " + e.getMessage(), e
            );
        }
    }

    /**
     * Parses YAML content and returns the result as a Map.
     * <p>
     * Convenience method when the expected YAML structure is a mapping.
     * </p>
     *
     * @param yamlContent the YAML string content to parse
     * @return the parsed Map representation
     * @throws IllegalArgumentException if yamlContent is null or empty
     * @throws YamlParsingException if parsing fails or result is not a Map
     */
    @SuppressWarnings("unchecked")
    public Map<String, Object> parseUserYamlAsMap(String yamlContent) {
        Object result = parseUserYaml(yamlContent);

        if (result instanceof Map) {
            return (Map<String, Object>) result;
        } else {
            throw new YamlParsingException(
                "Expected YAML content to represent a mapping (key-value pairs), " +
                "but got: " + result.getClass().getSimpleName()
            );
        }
    }

    /**
     * Custom exception class for YAML parsing errors.
     * <p>
     * This exception is thrown when the YAML content cannot be parsed
     * due to syntax errors, structural issues, or other parsing failures.
     * </p>
     */
    public static class YamlParsingException extends RuntimeException {

        /**
         * Constructs a new YamlParsingException with the specified detail message.
         *
         * @param message the detail message
         */
        public YamlParsingException(String message) {
            super(message);
        }

        /**
         * Constructs a new YamlParsingException with the specified detail message and cause.
         *
         * @param message the detail message
         * @param cause the cause of the exception
         */
        public YamlParsingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
